# -*- coding: utf-8 -*-
"""Obrys pevnin a hranice statu pro mapu na strance Sit.

Odkud to je: Natural Earth, sady `ne_110m_land` a
`ne_110m_admin_0_boundary_lines_land` - verejne dostupna data (public
domain), takze smi byt primo v repozitari. Nejhrubsi varianta (1:110
milionu) staci pro pohled na cely svet; pri vetsim priblizeni muze
spravce stahnout podrobnou mapu (mapa_podrobna.py) nebo zapnout podklad
z OpenStreetMap.

Projekce je **Web Mercator** - stejna, ve ktere jsou dlazdice
OpenStreetMap, takze na sebe sedi. Plocha je ctverec 360 x 360 jednotek:
x = zemepisna delka + 180, y = 180 - (180/pi) * ln(tan(pi/4 + sirka/2)).
Sirka je omezena na +-85,05 stupne (tam ma Mercator okraj ctverce);
Antarktida tak nekonci v nekonecnu. Obrys se z puvodni rovnobezkove
projekce prevedl jednorazovym skriptem a zaokrouhlil na setinu jednotky.

Data se nestahuji za behu a nikam se kvuli nim nechodi na sit.
"""

import math

# Cely svet v jednotkach Mercatoru - ctverec.
SIRKA = 360
VYSKA = 360

# Vychozi pohled (x, y, sirka, vyska): od 80 st. s. s. do 60 st. j. s.
# Polarni oblasti jsou v Mercatoru obri a nikdo se odtamtud nediva;
# posunout se k nim ale jde.
VYCHOZI = (0.0, 40.41, 360.0, 215.04)

# Kde ma Mercator okraj - dal na sever ani na jih uz nic neni.
MEZ_SIRKY = 85.05112878


def na_mapu(lat: float, lon: float) -> tuple[float, float]:
    """Zemepisne souradnice na souradnice v SVG (Web Mercator)."""
    lat = max(-MEZ_SIRKY, min(MEZ_SIRKY, float(lat)))
    y = 180.0 - (180.0 / math.pi) * math.log(
        math.tan(math.pi / 4 + math.radians(lat) / 2))
    return float(lon) + 180.0, y


